import csv
import io
import re


def parse_csv(raw_csv: str):
    columns = ["country_code", "latitude", "longitude", "country_name"]
    if raw_csv.startswith("\ufeff"):
        raw_csv = raw_csv[1:]

    rows = list(csv.reader(
        io.StringIO(raw_csv, newline=""),
        delimiter=",",
        quotechar='"',
        doublequote=True,
    ))

    code_labels = {"code", "countrycode", "countryid", "iso", "iso2", "isoalpha2", "alpha2"}
    latitude_labels = {"lat", "latitude"}
    longitude_labels = {"lon", "lng", "long", "longitude"}
    name_labels = {"name", "country", "countryname"}

    for index, row in enumerate(rows):
        if len(row) != 4:
            continue
        labels = [re.sub(r"[^a-z0-9]+", "", cell.casefold()) for cell in row]
        if (
            labels[0] in code_labels
            and labels[1] in latitude_labels
            and labels[2] in longitude_labels
            and labels[3] in name_labels
        ):
            columns = rows.pop(index)
            break
        try:
            float(row[1])
            float(row[2])
        except ValueError:
            continue
        break

    width = max(4, max((len(row) for row in rows), default=0))
    used_names = set(columns)
    for index in range(5, width + 1):
        name = f"extra_{index}"
        while name in used_names:
            name += "_"
        columns.append(name)
        used_names.add(name)

    return {
        "columns": columns,
        "rows": [row + [""] * (width - len(row)) for row in rows],
    }
